var numInterf = 10;
var widthInterf = 40;
var photonDim=5;
var iMax = 100;
var d = 150;
var b= 100;
var f = 30;

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(0);
	frameRate (10);

}


function draw() {
		noStroke();
		push();
		translate(width/2, height/2);
		for (var j=-90;j<=90;j=j+0.2){
			var I = 200*pow(cos(PI*d*sin(radians(j))/f),2)*pow(sin(PI*b*sin(radians(j))/f)/(PI*b*sin(radians(j))/f),2);
			var alfa;
			alfa = map (I, 0, 200, 0, 255);
			fill(255, alfa);

			//ellipse(map(j, -90, 90, 50, 800), map(I, 0, 200, 100, 600), 1, 1);
			ellipse(map(j, -90, 90, -400, 400), random(-windowHeight/2, windowHeight/2), photonDim, photonDim);
		}
		pop();
}

